import{_ as n,C as o,o as d,c as e,j as i,E as r,a as l,a3 as s}from"./chunks/framework.C6R8kWFE.js";const p=JSON.parse(`{"title":"3-hafta (Mentor)","description":"","frontmatter":{"title":"3-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"n":3,"bob":"II-bob · 2D grafika asoslari va Photoshop","lessons":[{"g":7,"title":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","lead":"Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash va assetlar kollaji","link":"/mentor/9-sinf-game/hafta-03/dars-1","slide":"/slaydlar/9-sinf-game/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-1-test.html"},{"g":8,"title":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","lead":"Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK, rang g'ildiragi va rang psixologiyasi","link":"/mentor/9-sinf-game/hafta-03/dars-2","slide":"/slaydlar/9-sinf-game/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-2-test.html"},{"g":9,"title":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","lead":"Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient bilan ishlash","link":"/mentor/9-sinf-game/hafta-03/dars-3","slide":"/slaydlar/9-sinf-game/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-game/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf-game/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-03/index.md","filePath":"mentor/9-sinf-game/hafta-03/index.md"}`),h={name:"mentor/9-sinf-game/hafta-03/index.md"},g={class:"blk"},m={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},y={class:"blk"},u={id:"baholash-mezoni",tabindex:"-1"};function c(v,a,b,k,q,f){const t=o("Icon");return d(),e("div",null,[i("div",g,[i("h2",m,[r(t,{name:"house"}),a[0]||(a[0]=l(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=s('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h2 id="_7-dars-photoshop-interfeysi-va-vositalari-3-qism-qatlamlar-arxitekturasi-va-assetlar-kollaji" tabindex="-1">7-dars: Photoshop interfeysi va vositalari (3-qism): Qatlamlar arxitekturasi va assetlar kollaji <a class="header-anchor" href="#_7-dars-photoshop-interfeysi-va-vositalari-3-qism-qatlamlar-arxitekturasi-va-assetlar-kollaji" aria-label="Permalink to &quot;7-dars: Photoshop interfeysi va vositalari (3-qism): Qatlamlar arxitekturasi va assetlar kollaji&quot;">​</a></h2><ol><li>Ko&#39;p qatlamli o&#39;yin loyihalarida nima uchun qatlamlarni <code>[01_Background]</code>, <code>[02_Midground]</code>, <code>[03_Foreground]</code>, <code>[04_UI_HUD]</code> guruhlariga (<code>Ctrl + G</code>) ajratish zarurligini tushuntiring.</li><li>Oddiy rastr qatlamni kichraytirib yana kattalashtirgandagi piksel yo&#39;qolishi bilan <strong>Smart Object</strong> himoyasi o&#39;rtasidagi farqni 3 ta jumlada tasvirlang.</li><li>Dumaloq metall qalqonga zang yoki kosmik teksturani bog&#39;lashda <strong>Clipping Mask (<code>Ctrl + Alt + G</code>)</strong> qanday ishlashini amaliy bosqichlarda yozing.</li><li>O&#39;yin obyekti fonda havoda muallaq turgandek ko&#39;rinmasligi uchun <strong>Kontakt soyasi (Contact Shadow)</strong> qaysi rejimda (<code>Multiply</code>) va qanday parametrli cho&#39;tka bilan chiziladi?</li></ol><hr><h2 id="_8-dars-ranglar-nazariyasi-va-dizayn-asoslari-1-qism-rgb-vs-cmyk-rang-g-ildiragi-va-rang-psixologiyasi" tabindex="-1">8-dars: Ranglar nazariyasi va dizayn asoslari (1-qism): RGB vs CMYK, rang g&#39;ildiragi va rang psixologiyasi <a class="header-anchor" href="#_8-dars-ranglar-nazariyasi-va-dizayn-asoslari-1-qism-rgb-vs-cmyk-rang-g-ildiragi-va-rang-psixologiyasi" aria-label="Permalink to &quot;8-dars: Ranglar nazariyasi va dizayn asoslari (1-qism): RGB vs CMYK, rang g&#39;ildiragi va rang psixologiyasi&quot;">​</a></h2><ol><li>Nima sababdan kompyuter va smartfon o&#39;yinlari uchun grafik assetlar faqat <strong>RGB</strong> (additiv) modelida tayyorlanishi shart va nega <strong>CMYK</strong> o&#39;yin dvijoklarida ishlatilmaydi?</li><li>Yoxannes Itten rang g&#39;ildiragidagi 3 ta birlamchi rang (Qizil, Sariq, Ko&#39;k) asosida qaysi 3 ta ikkilamchi ranglar qanday hosil bo&#39;lishini yozing.</li><li>Yashil o&#39;rmon sahnasida harakatlanuvchi qahramon ko&#39;zga darhol tashlanishi uchun <strong>Komplementar kontrast</strong> qoidasi bo&#39;yicha uning libosiga qaysi rang tanlanishi kerak?</li><li>O&#39;yindagi 3 xil sehrli ichimlik (Potion) uchun rang psixologiyasiga muvofiq ranglar tanlang: Jon to&#39;ldiruvchi (Health), Sehr quvvati (Mana) va Chidamlilik (Stamina).</li></ol><hr><h2 id="_9-dars-ranglar-nazariyasi-va-dizayn-asoslari-2-qism-color-picker-swatches-va-gradient-tool" tabindex="-1">9-dars: Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient Tool <a class="header-anchor" href="#_9-dars-ranglar-nazariyasi-va-dizayn-asoslari-2-qism-color-picker-swatches-va-gradient-tool" aria-label="Permalink to &quot;9-dars: Ranglar nazariyasi va dizayn asoslari (2-qism): Color Picker, Swatches va Gradient Tool&quot;">​</a></h2><ol><li>Dizaynerlar uchun eng qulay bo&#39;lgan <strong>HSB</strong> modelining 3 ta parametri (Hue, Saturation, Brightness) nimani anglatishini va ularning qiymat oraliqlarini ko&#39;rsating.</li><li>O&#39;yin yaratishda nima sababdan tasodifiy ranglar ishlatilmay, <strong>Swatches</strong> panelida 4–6 ta asosiy rangdan iborat rasmiy o&#39;yin palitrasi saqlanishi kerak?</li><li>O&#39;yin sahnasiga quyosh chiqishi osmonini chizish uchun <strong>Linear Gradient</strong>, qahramon atrofidagi aylanma sehrli nurni chizish uchun esa <strong>Radial Gradient</strong> qanday ishlatilishini tushuntiring.</li><li>Katta ekranda silliq gradiyent o&#39;tishi o&#39;rniga pog&#39;onali yoqimsiz chandiqlar (<strong>Color Banding</strong>) paydo bo&#39;lganda, buni bartaraf etish uchun Photoshopda qaysi filtr (Noise) qo&#39;llaniladi?</li></ol><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><h3 id="baholash-mezonlari-jami-100-ball" tabindex="-1">Baholash mezonlari (Jami 100 ball) <a class="header-anchor" href="#baholash-mezonlari-jami-100-ball" aria-label="Permalink to &quot;Baholash mezonlari (Jami 100 ball)&quot;">​</a></h3><ul><li><strong>7-dars vazifasi (30 ball):</strong> Qatlamlar arxitekturasi, Smart Objects afzalligi, Clipping Mask mexanizmi va kontakt soyalari texnikasi to&#39;g&#39;ri bayon etilgani.</li><li><strong>8-dars vazifasi (35 ball):</strong> RGB va CMYK farqi, Itten g&#39;ildiragi turlari, komplementar kontrast va o&#39;yin UI elementlarida rang psixologiyasi asosli tahlil qilingani.</li><li><strong>9-dars vazifasi (35 ball):</strong> HSB va HEX modellarini tushunish, Swatches palitrasi tartibi hamda Linear va Radial gradiyentlarni o&#39;yin elementlariga to&#39;g&#39;ri tatbiq etish.</li></ul><h3 id="eslatma" tabindex="-1">Eslatma <a class="header-anchor" href="#eslatma" aria-label="Permalink to &quot;Eslatma&quot;">​</a></h3><ul><li>O&#39;quvchilar javoblari bilan birga Photoshopda bajarilgan amaliy ishlar skrinshotlarini yoki <code>.psd</code> fayllarini ilova qilishlari tavsiya etiladi.</li></ul>',16))]),i("div",y,[i("h2",u,[r(t,{name:"list-checks"}),a[3]||(a[3]=l(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=s('<p><strong>Mavzular:</strong></p><ol><li>Photoshop interfeysi va vositalari (3-qism): Qatlamlar bilan amaliy ishlash, guruhlash, Smart Objects, Clipping Masks va assetlar kollaji</li><li>Ranglar nazariyasi va dizayn asoslari (1-qism): RGB va CMYK modellari, Yoxannes Itten rang g&#39;ildiragi, rang uyg&#39;unliklari va rang psixologiyasi</li><li>Ranglar nazariyasi va dizayn asoslari (2-qism): Dizayn tamoyillari (kompozitsiya, vizual ierarxiya, kontrast), Color Picker (HSB, HEX), Swatches va Gradient Tool</li></ol><hr><h2 id="baholash-mezonlari" tabindex="-1">Baholash mezonlari <a class="header-anchor" href="#baholash-mezonlari" aria-label="Permalink to &quot;Baholash mezonlari&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mezon</th><th>Tavsif</th><th>Maks. ball</th></tr></thead><tbody><tr><td><strong>Qatlamlar va Assetlar Kollaji</strong></td><td>Guruhlash tartibi, Smart Object xavfsizligi, Clipping Mask qo&#39;llanilishi, kontakt soyalari va yorug&#39;lik yo&#39;nalishi</td><td>30 ball</td></tr><tr><td><strong>Ranglar Nazariyasi va Psixologiyasi</strong></td><td>RGB vs CMYK, Itten doirasi (birlamchi, ikkilamchi, uchlamchi), komplementar va analog sxemalar, o&#39;yin rang kodi</td><td>35 ball</td></tr><tr><td><strong>Dizayn Asoslari va Rang Vositalari</strong></td><td>Vizual ierarxiya, HSB va HEX koordinatalari, Swatches palitrasi, Linear va Radial gradiyent amaliyoti</td><td>35 ball</td></tr><tr><td><strong>JAMI</strong></td><td></td><td><strong>100 ball</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>Qatlamlar &amp; Kollaj (30)</th><th>Ranglar Nazariyasi (35)</th><th>Dizayn &amp; Vositalar (35)</th><th>Jami ball (100)</th><th>Izoh</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="mentor-qaydlari-va-tahlil" tabindex="-1">Mentor qaydlari va tahlil <a class="header-anchor" href="#mentor-qaydlari-va-tahlil" aria-label="Permalink to &quot;Mentor qaydlari va tahlil&quot;">​</a></h2><ul><li><strong>Darsdagi asosiy qiyinchiliklar:</strong> O&#39;quvchilar rang tanlashda ko&#39;pincha barcha elementlarni birdek to&#39;yingan (100% Saturation) qilib yuborishadi (&quot;kislotali ranglar&quot;). &quot;60-30-10&quot; qoidasini va neytral fon ahamiyatini tushuntirish lozim. Shuningdek, komplementar ranglar orasida gradiyent tortilganda o&#39;rtada kulrang ifloslanish paydo bo&#39;lishining oldini olish uchun oraliq ranglar qo&#39;yish amaliyotini o&#39;rgatish zarur.</li><li><strong>Iqtidorli o&#39;quvchilar uchun:</strong> O&#39;z o&#39;yinlari uchun to&#39;liq rang pasportini (Color Bible) shakllantirish, o&#39;yin darajasi uchun <code>.aco</code> formatidagi Swatches palitrasini eksport qilish va 3 ta o&#39;lja nodirligi (Loot Rarity) ramkalarini gradiyentlar bilan bezash topshirig&#39;i berilishi mumkin.</li></ul>',11))])])}const x=n(h,[["render",c]]);export{p as __pageData,x as default};
